Exactly one existing code fence changed. Parent smoke: setLocale('fr') followed by setLocale('en') with the first import rejecting must return false for the first rather than throw; a current failed import still rejects and permits explicit retry; an aborted pending selection must not commit locale; an already aborted call must not supersede a current valid selection. Changed snippet:
async function setLocale(locale: Locale, signal?: AbortSignal): Promise<boolean> {
  if (signal?.aborted) return false
  const ticket = ++generation
  const current = () => ticket === generation && !signal?.aborted
  try {
    await ensureLocale(locale)
  } catch (error) {
    if (!current()) return false
    throw error
  }
  if (!current()) return false
  i18n.global.locale.value = locale
  await nextTick()
  return current()
}
